def choose_half(nums: List[int], target: int) -> str:
    l = 0
    r = len(nums) - 1
    mid = (l + r) // 2
    if nums[l] <= nums[mid]:
        if nums[l] <= target < nums[mid]:
            return 'left'
        return 'right'
    if nums[mid] < target <= nums[r]:
        return 'right'
    return 'left'

